// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }

    // fuzz the caller address and an amount to deposit; the distinguishing behavior
    // arises when credit == 0 and the callee reverts on receiving a call with value 0
    function testFuzz_property(address caller, uint256 depositAmount) public {
        vm.assume(depositAmount <= VALUE_CAP);
        // keep domain wide but reasonable for deposit amounts
        depositAmount = bound(depositAmount, 0, 1 ether);

        // Deploy a helper that can be set to revert on receive; we will use the helper
        // as the caller (msg.sender) so that when c.call{value:...}(msg.sender) happens,
        // the helper's fallback/receive runs and can revert.
        ReverterReceiver reverter = new ReverterReceiver();

        // Fund the helper and the fuzzed caller address so they can act as EOAs
        vm.deal(address(reverter), 1 ether);
        vm.deal(caller, 1 ether);

        // Case setup: if depositAmount > 0, have 'caller' deposit some funds into c
        if (depositAmount > 0) {
            vm.prank(caller);
            c.deposit{value: depositAmount}();
            // At this point caller has credit == depositAmount
        }

        // Ensure the helper will revert on any call it receives. For the distinguishing
        // behavior we use the helper as the msg.sender in withdrawAll by impersonating it.
        reverter.setShouldRevert(true);

        // If we want to observe the scenario where credit is zero, we must impersonate
        // the helper (which currently has credit 0) to call withdrawAll. The reference
        // contract checks oCredit>0 and will simply return (no external call, no revert).
        // The mutant checks oCredit>=0 and will attempt the external call even with 0 value,
        // which will hit the helper and, since it reverts, cause withdrawAll to revert.

        bool ok;
        vm.prank(address(reverter));
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule (single assertion): For the correct contract, when the caller has
        // zero credit, withdrawAll never reverts. Therefore ok must be true when the
        // caller's credit is zero. We assert that if the helper's credit is zero then ok==true.
        // This holds for the reference implementation for all inputs, but the mutant can
        // make ok==false for the helper (credit==0) because it still calls the helper which reverts.
        uint recordedCredit = address(c).balance; // placeholder to satisfy reading c; but we MUST read credit via public surface
        // The contract's credit mapping is private in the given C; we cannot read it directly.
        // Instead, the distinguishing observable is whether the call reverted when a caller with zero credit invokes withdrawAll.
        // We therefore assert that ok is true when the caller had zero credit. Determine whether the helper had zero credit:

        // The helper never deposited, so its credit in c should be zero. We express the rule directly:
        assertTrue(ok);
    }
}

// Helper that reverts when receiving a call (used as the msg.sender destination)
contract ReverterReceiver {
    bool public shouldRevert;
    function setShouldRevert(bool v) external { shouldRevert = v; }
    receive() external payable {
        if (shouldRevert) revert("revert on receive");
    }
    fallback() external payable {
        if (shouldRevert) revert("revert on fallback");
    }
}
